/**
 * Read-only client for the project workflow viewer API (`contracts/projects/README.md`).
 *
 * Every payload is validated against the committed contract schemas before it reaches a component. A
 * response that fails validation is a malformed-payload error: nothing is patched up or substituted.
 * Artifacts and results are only ever requested through the scoped routes of the run being viewed.
 */
import { z } from 'zod'
import {
  isBlockingFinding,
  schemas,
  validateReviewResult,
  validateRunDetail,
  validateRunInputs,
  type Project,
  type ReviewFinding,
  type ReviewResult,
  type RunDetail,
  type RunInputs,
  type RunInputWorker,
  type RunSummary,
  type WorkflowDefinition,
} from '../../contracts/projects/v1.ts'
import { eventSchema, validateWorkerResult, type WorkerResult, type WorkflowEvent } from '../../contracts/workflow/v1.ts'

export type { Project, ReviewFinding, ReviewResult, RunDetail, RunInputs, RunInputWorker, RunSummary, WorkflowDefinition, WorkerResult, WorkflowEvent }
export { isBlockingFinding }

/** The contract's "not recorded" 404 codes: a run whose export predates a section, never an error state. */
export const NOT_RECORDED = { review: 'REVIEW_NOT_FOUND', inputs: 'INPUTS_NOT_FOUND' } as const

export type ApiErrorKind = 'network' | 'http' | 'malformed'

/** A failed request. `status` is set for HTTP failures; `code` comes from the contract error body when present. */
export class ProjectsApiError extends Error {
  readonly kind: ApiErrorKind
  readonly status: number | null
  readonly code: string | null
  readonly path: string

  constructor(kind: ApiErrorKind, message: string, path: string, options: { status?: number | null; code?: string | null } = {}) {
    super(message)
    this.name = 'ProjectsApiError'
    this.kind = kind
    this.status = options.status ?? null
    this.code = options.code ?? null
    this.path = path
  }

  get notFound(): boolean {
    return this.kind === 'http' && this.status === 404
  }
}

export function describeApiError(error: unknown): string {
  if (error instanceof ProjectsApiError) {
    switch (error.kind) {
      case 'network': return 'The API could not be reached. Check that the server is running, then retry.'
      case 'malformed': return `The API returned data that does not match the projects contract: ${error.message}`
      case 'http': return error.code ? `${error.message} (${error.code}, HTTP ${error.status})` : `${error.message} (HTTP ${error.status})`
    }
  }
  return error instanceof Error && error.message ? error.message : 'An unexpected error occurred.'
}

const errorBodySchema = z.object({ error: z.object({ code: z.string(), message: z.string() }) })

function encodeSegments(...segments: string[]): string {
  return segments.map(encodeURIComponent).join('/')
}

export type RunScope = { projectId: string; workflowId: string; runId: string }

export const paths = {
  projects: () => '/api/projects',
  workflows: (projectId: string) => `/api/projects/${encodeSegments(projectId)}/workflows`,
  runs: (projectId: string, workflowId: string, options: { limit?: number; cursor?: string | null } = {}) => {
    const query = new URLSearchParams()
    if (options.limit !== undefined) query.set('limit', String(options.limit))
    if (options.cursor) query.set('cursor', options.cursor)
    const suffix = query.size ? `?${query}` : ''
    return `/api/projects/${encodeSegments(projectId)}/workflows/${encodeSegments(workflowId)}/runs${suffix}`
  },
  run: (scope: RunScope) => `/api/projects/${encodeSegments(scope.projectId)}/workflows/${encodeSegments(scope.workflowId)}/runs/${encodeSegments(scope.runId)}`,
  events: (scope: RunScope, after = 0) => `${paths.run(scope)}/events?after=${after}`,
  result: (scope: RunScope, nodeId: string, attempt: number) => `${paths.run(scope)}/results/${encodeSegments(nodeId)}/${attempt}`,
  artifact: (scope: RunScope, artifactId: string) => `${paths.run(scope)}/artifacts/${encodeSegments(artifactId)}`,
  review: (scope: RunScope, attempt: number) => `${paths.run(scope)}/reviews/${attempt}`,
  inputs: (scope: RunScope) => `${paths.run(scope)}/inputs`,
}

async function request(path: string, signal: AbortSignal | undefined, accept: string): Promise<Response> {
  let response: Response
  try {
    response = await fetch(path, { signal, headers: { Accept: accept } })
  } catch (error) {
    if (signal?.aborted) throw error
    throw new ProjectsApiError('network', error instanceof Error ? error.message : 'Network failure', path)
  }
  if (!response.ok) {
    let body: unknown = null
    try { body = await response.json() } catch { /* not JSON */ }
    const parsed = errorBodySchema.safeParse(body)
    const message = parsed.success ? parsed.data.error.message : `The API responded with status ${response.status}.`
    throw new ProjectsApiError('http', message, path, { status: response.status, code: parsed.success ? parsed.data.error.code : null })
  }
  return response
}

async function requestJson<T>(path: string, validate: (input: unknown) => T, signal?: AbortSignal): Promise<T> {
  const response = await request(path, signal, 'application/json')
  let body: unknown
  try {
    body = await response.json()
  } catch {
    throw new ProjectsApiError('malformed', 'the response body is not JSON.', path)
  }
  try {
    return validate(body)
  } catch (error) {
    throw new ProjectsApiError('malformed', error instanceof z.ZodError ? z.prettifyError(error) : error instanceof Error ? error.message : 'invalid payload', path)
  }
}

export function fetchProjects(signal?: AbortSignal): Promise<Project[]> {
  return requestJson(paths.projects(), input => schemas.projectList.parse(input).projects, signal)
}

export function fetchWorkflows(projectId: string, signal?: AbortSignal): Promise<WorkflowDefinition[]> {
  return requestJson(paths.workflows(projectId), input => schemas.workflowList.parse(input).workflows, signal)
}

export type RunPage = { runs: RunSummary[]; nextCursor: string | null }

export function fetchRuns(projectId: string, workflowId: string, options: { cursor?: string | null } = {}, signal?: AbortSignal): Promise<RunPage> {
  return requestJson(paths.runs(projectId, workflowId, options), input => {
    const page = schemas.runList.parse(input)
    for (const run of page.runs) {
      if (run.project_id !== projectId || run.workflow_id !== workflowId) throw new Error(`run ${run.run_id} belongs to another scope.`)
    }
    return { runs: page.runs, nextCursor: page.next_cursor }
  }, signal)
}

export function fetchRunDetail(scope: RunScope, signal?: AbortSignal): Promise<RunDetail> {
  return requestJson(paths.run(scope), input => {
    const detail = validateRunDetail(input)
    if (detail.summary.project_id !== scope.projectId || detail.summary.workflow_id !== scope.workflowId || detail.summary.run_id !== scope.runId) {
      throw new Error('the run detail belongs to a different project, workflow or run.')
    }
    return detail
  }, signal)
}

const eventListSchema = z.strictObject({ events: z.array(eventSchema) })

export function fetchEvents(scope: RunScope, signal?: AbortSignal): Promise<WorkflowEvent[]> {
  return requestJson(paths.events(scope, 0), input => {
    const events = eventListSchema.parse(input).events
    // Deduplicate by sequence and keep the persisted order; the run ID must be this run's.
    const seen = new Set<number>()
    const unique: WorkflowEvent[] = []
    for (const event of events) {
      if (event.run_id !== scope.runId) throw new Error(`event ${event.event_id} belongs to run ${event.run_id}.`)
      if (seen.has(event.sequence)) continue
      seen.add(event.sequence)
      unique.push(event)
    }
    return unique.sort((a, b) => a.sequence - b.sequence)
  }, signal)
}

/** Only results published under this run's scoped `results/` route are fetched; anything else is refused. */
export function scopedResultPath(scope: RunScope, resultUri: string): string | null {
  const prefix = `${paths.run(scope)}/results/`
  if (!resultUri.startsWith(prefix)) return null
  const rest = resultUri.slice(prefix.length).split('/')
  if (rest.length !== 2 || rest.some(segment => segment === '') || !/^[1-9][0-9]*$/.test(rest[1])) return null
  return resultUri
}

export function fetchWorkerResult(scope: RunScope, resultPath: string, signal?: AbortSignal): Promise<WorkerResult> {
  return requestJson(resultPath, input => {
    const result = validateWorkerResult(input)
    if (result.run_id !== scope.runId) throw new Error(`the result belongs to run ${result.run_id}.`)
    return result
  }, signal)
}

/** Text artifacts (logs, reports, patches) are read as plain text and rendered as text, never as HTML. */
export async function fetchArtifactText(scope: RunScope, artifactId: string, signal?: AbortSignal): Promise<string> {
  const response = await request(paths.artifact(scope, artifactId), signal, 'text/plain, */*')
  return response.text()
}

/** Only reviews published under this run's scoped `reviews/` route are fetched; anything else is refused. */
export function scopedReviewPath(scope: RunScope, resultUri: string): string | null {
  const prefix = `${paths.run(scope)}/reviews/`
  if (!resultUri.startsWith(prefix)) return null
  if (!/^[1-9][0-9]*$/.test(resultUri.slice(prefix.length))) return null
  return resultUri
}

export function fetchReviewResult(scope: RunScope, reviewPath: string, signal?: AbortSignal): Promise<ReviewResult> {
  return requestJson(reviewPath, input => {
    const review = validateReviewResult(input)
    if (review.run_id !== scope.runId) throw new Error(`the review belongs to run ${review.run_id}.`)
    return review
  }, signal)
}

export function fetchRunInputs(scope: RunScope, signal?: AbortSignal): Promise<RunInputs> {
  return requestJson(paths.inputs(scope), input => {
    const inputs = validateRunInputs(input)
    if (inputs.run_id !== scope.runId) throw new Error(`the inputs belong to run ${inputs.run_id}.`)
    return inputs
  }, signal)
}

/** Whether a failure is the contract's 404 for a section the run's export does not carry. */
export function isNotRecorded(error: unknown, code: string): boolean {
  return error instanceof ProjectsApiError && error.notFound && error.code === code
}

/** Resolves to null when the section is not recorded (the contract's 404 code); every other failure propagates. */
export async function orNotRecorded<T>(request: Promise<T>, code: string): Promise<T | null> {
  try {
    return await request
  } catch (error) {
    if (isNotRecorded(error, code)) return null
    throw error
  }
}
import { useEffect, useRef, useState, type MouseEvent } from 'react'
import { Markdown } from '../document/Markdown.tsx'
import type { RunInputWorker, WorkerResult } from './api.ts'
import { formatDuration, formatTime } from './status.ts'
import type { Resource } from './useResource.ts'

type TaskProps = {
  worker: RunInputWorker
  /** The node's published result, when it loaded: required checks are matched to executed checks by exact command. */
  result: Resource<WorkerResult>
  /** A requirement quote to highlight in the task source, handed over by a finding link; null otherwise. */
  highlight: string | null
  /** Called once the highlight has been applied, so the run view forgets it (leaving the node drops it anyway). */
  onHighlightApplied: () => void
}

/** Scrolls to and focuses an executed check in the evidence list without touching the history. */
function jumpToCheck(event: MouseEvent<HTMLAnchorElement>, id: string) {
  const target = document.getElementById(id)
  if (!target) return
  event.preventDefault()
  target.scrollIntoView({ block: 'center' })
  target.focus()
}

/**
 * The pinned task of a worker: rendered Markdown or the exact source, the ownership boundary and the
 * required checks. When a finding link hands over a quote, the panel opens on the source with the quote
 * marked and scrolled into view. The quote is captured when the panel mounts (the node detail remounts per
 * node), so clearing the pending hand-off afterwards does not remove the mark until the reader leaves.
 */
export function TaskPanel({ worker, result, highlight, onHighlightApplied }: TaskProps) {
  const [view, setView] = useState<'rendered' | 'source'>(() => (highlight === null ? 'rendered' : 'source'))
  const [activeQuote] = useState(() => highlight)
  const markRef = useRef<HTMLElement>(null)
  useEffect(() => {
    if (activeQuote === null) return
    markRef.current?.scrollIntoView({ block: 'center' })
    onHighlightApplied()
  }, [activeQuote, onHighlightApplied])

  const text = worker.task.text
  const index = activeQuote === null ? -1 : text.indexOf(activeQuote)
  const executed = result.status === 'ready' ? result.data.checks : null

  return (
    <section className="evidence-section task-panel" aria-labelledby="task-title" data-testid="task-panel">
      <div className="task-head">
        <h4 id="task-title">Task</h4>
        <div role="group" aria-label="Task view" className="task-toggle">
          <button type="button" className="button button-small" aria-pressed={view === 'rendered'} onClick={() => setView('rendered')}>Rendered</button>
          <button type="button" className="button button-small" aria-pressed={view === 'source'} onClick={() => setView('source')}>Source</button>
        </div>
      </div>
      <p className="projects-muted">The assignment pinned in the run plan: the authored task plus the appended ownership and checks.</p>
      {worker.task.truncated && (
        <p className="projects-notice" role="note" data-testid="task-truncated">The task text was truncated by the viewer API; the marker at its end says how many characters were left out.</p>
      )}
      {activeQuote !== null && index === -1 && (
        <p className="projects-muted" data-testid="task-highlight-missing">The quoted requirement was not found in this task text, so nothing is highlighted.</p>
      )}
      {view === 'rendered' ? (
        <div className="task-rendered"><Markdown content={text} /></div>
      ) : (
        <pre className="task-source" data-testid="task-source" tabIndex={0}>
          {index === -1 ? text : (
            <>
              {text.slice(0, index)}
              <mark ref={markRef} className="task-highlight" data-testid="task-highlight">{activeQuote}</mark>
              {text.slice(index + activeQuote!.length)}
            </>
          )}
        </pre>
      )}

      <h5 id="task-owned-title">Owned paths</h5>
      {worker.owned_paths.length === 0 ? (
        <p className="projects-muted">No owned paths were pinned.</p>
      ) : (
        <ul className="evidence-list evidence-files" data-testid="task-owned-paths" aria-labelledby="task-owned-title">
          {worker.owned_paths.map(path => <li key={path}><code>{path}</code></li>)}
        </ul>
      )}

      <h5 id="task-checks-title">Required checks</h5>
      <p className="projects-muted" data-testid="task-required-kinds">
        Required check kinds for this lane: {worker.required_check_kinds.length === 0 ? 'none pinned' : worker.required_check_kinds.join(', ')}
      </p>
      {worker.checks.length === 0 ? (
        <p className="projects-muted">No checks were required.</p>
      ) : (
        <ul className="evidence-list task-checks" data-testid="task-checks" aria-labelledby="task-checks-title">
          {worker.checks.map(check => {
            const executedIndex = executed === null ? -1 : executed.findIndex(candidate => candidate.command === check.command)
            return (
              <li key={check.id} data-check-id={check.id}>
                <code>{check.command}</code>
                <span className="projects-muted"> · {check.id} · {check.kind} · timeout {formatDuration(check.timeout_seconds)}</span>
                {check.scenarios.length > 0 && (
                  <span className="projects-muted"> · {check.scenarios.length} {check.scenarios.length === 1 ? 'scenario' : 'scenarios'}: {check.scenarios.map(scenario => scenario.id).join(', ')}</span>
                )}
                <div className="task-check-status">
                  {executed === null ? (
                    <span className="projects-muted">{result.status === 'loading' ? 'Loading the published result to compare…' : 'No published result to compare against.'}</span>
                  ) : executedIndex === -1 ? (
                    <span className="projects-muted">not executed in this result</span>
                  ) : (
                    <a href={`#check-${executedIndex}`} onClick={event => jumpToCheck(event, `check-${executedIndex}`)}>
                      executed as check {executedIndex + 1}: exit {executed[executedIndex].exit_code}
                    </a>
                  )}
                </div>
              </li>
            )
          })}
        </ul>
      )}

      {worker.prompt === null ? (
        <p className="projects-muted" data-testid="task-prompt-none">The exact prompt was not recorded for this run (it predates prompt capture).</p>
      ) : (
        <details className="task-prompt" data-testid="task-prompt">
          <summary>Exact prompt the session received{worker.prompt.truncated ? ' (truncated by the viewer API)' : ''}</summary>
          <pre className="task-source">{worker.prompt.text}</pre>
        </details>
      )}
    </section>
  )
}

export function LaunchReceipt({ launch }: { launch: RunInputWorker['launch'] }) {
  return (
    <section className="evidence-section" aria-labelledby="launch-receipt-title" data-testid="launch-receipt">
      <h4 id="launch-receipt-title">Launch receipt</h4>
      {launch === null ? (
        <p className="projects-muted" data-testid="launch-none">No launch receipt recorded.</p>
      ) : (
        <dl className="projects-facts">
          <div><dt>Session</dt><dd>{launch.session_id === null ? 'Not yet reported by the launcher' : <code>{launch.session_id}</code>}</dd></div>
          <div><dt>Launch requested</dt><dd>{formatTime(launch.launch_requested_at)}</dd></div>
          <div><dt>Native start</dt><dd>{launch.native_started_at === null ? 'Not reported' : formatTime(launch.native_started_at)}</dd></div>
          <div><dt>Observed state</dt><dd>{launch.observed_state ?? 'Not observed'}</dd></div>
          <div><dt>Launcher status</dt><dd><code>{launch.status}</code></dd></div>
          <div><dt>Launcher invocations</dt><dd>{launch.launcher_invocations}</dd></div>
        </dl>
      )}
    </section>
  )
}

function Assumptions({ items }: { items: string[] }) {
  if (items.length === 0) return <p className="projects-muted">No open assumptions.</p>
  return <ul className="evidence-list">{items.map((item, index) => <li key={index}>{item}</li>)}</ul>
}

/** The worker's own completion signal, and the accepted handoff only when it differs from it. */
export function WorkerSignals({ completion, handoff }: { completion: RunInputWorker['completion']; handoff: RunInputWorker['handoff'] }) {
  const handoffDiffers = handoff !== null && (
    completion === null || handoff.summary !== completion.summary || JSON.stringify(handoff.open_assumptions) !== JSON.stringify(completion.open_assumptions)
  )
  return (
    <>
      <section className="evidence-section" aria-labelledby="worker-completion-title" data-testid="worker-completion">
        <h4 id="worker-completion-title">Reported by the worker</h4>
        {completion === null ? (
          <p className="projects-muted">No completion signal recorded.</p>
        ) : (
          <>
            <p>
              <span className={`status-badge ${completion.status === 'completed' ? 'status-succeeded' : 'status-failed'}`} data-status={completion.status}><span>{completion.status}</span></span>
              {' '}<span className="projects-muted">as signalled by the session itself, not a verified result.</span>
            </p>
            <p className="worker-summary">{completion.summary}</p>
            <Assumptions items={completion.open_assumptions} />
          </>
        )}
      </section>
      {handoffDiffers && (
        <section className="evidence-section" aria-labelledby="worker-handoff-title" data-testid="worker-handoff">
          <h4 id="worker-handoff-title">Handoff as accepted</h4>
          <p className="projects-muted">The accepted handoff differs from what the worker reported.</p>
          <p className="worker-summary">{handoff.summary}</p>
          <Assumptions items={handoff.open_assumptions} />
        </section>
      )}
    </>
  )
}

export function StopLine({ stop }: { stop: RunInputWorker['stop'] }) {
  const confirmed = stop !== null && stop.stopped && stop.confirmed_at !== null
  return (
    <p className="worker-stop" data-testid="worker-stop">
      {confirmed
        ? `Stop confirmed at ${formatTime(stop.confirmed_at!)}.`
        : stop === null ? 'Stop not confirmed: no stop receipt was recorded.' : 'Stop not confirmed: the stop receipt records no confirmation.'}
    </p>
  )
}

