/** A character that can continue a repo-relative path, so a match followed or preceded by one names a different path. */
const PATH_CHAR = /[A-Za-z0-9_\-/.]/

/**
 * Every position where `message` names `path` verbatim as a whole path: the characters around the match must not
 * extend it (`src/a.ts` is not named by `src/a.tsx` or `lib/src/a.ts`). A trailing full stop ends a sentence, not the
 * path. Nothing is inferred from similar names or partial paths (PRD_VIEWER_CLARITY section 2).
 */
function pathOccurrences(message: string, path: string): number[] {
  const found: number[] = []
  if (path.length === 0) return found
  for (let index = message.indexOf(path); index !== -1; index = message.indexOf(path, index + 1)) {
    const before = index === 0 ? '' : message[index - 1]
    const end = index + path.length
    const after = message[end] ?? ''
    const extendsAfter = after === '.' ? PATH_CHAR.test(message[end + 1] ?? '') && message[end + 1] !== '.' && message[end + 1] !== '/' ? true : false : PATH_CHAR.test(after)
    if (before !== '' && PATH_CHAR.test(before)) continue
    if (after !== '' && extendsAfter) continue
    found.push(index)
  }
  return found
}

/** The findings whose message names `path` verbatim, in review order. */
export function findingsForFile<T extends Pick<ReviewFinding, 'message'>>(findings: readonly T[], path: string): T[] {
  return findings.filter(finding => pathOccurrences(finding.message, path).length > 0)
}

/** The `[from, to]` line ranges from every `path:N` and `path:N-M` occurrence in `message`, in message order. */
export function linesNamed(message: string, path: string): [number, number][] {
  const ranges: [number, number][] = []
  for (const index of pathOccurrences(message, path)) {
    const match = /^:(\d+)(?:-(\d+))?/.exec(message.slice(index + path.length))
    if (!match) continue
    const from = Number(match[1])
    const to = match[2] === undefined ? from : Number(match[2])
    if (from < 1) continue
    ranges.push(from <= to ? [from, to] : [to, from])
  }
  return ranges
}
EOF

